mapper.select:
SELECT
		to_char(t.operation_start_date,'yyyy-MM-dd')   VDATE,
		to_char(t.auto_redeem_date,'yyyy-MM-dd')    RDATE,
		t.HOLD_DAYS HOLDDAYS,
       /*超额业绩报酬*/
		ABOVE_AMT ABOVE_AMT,
  		/*超额业绩报酬-确认金额*/
		nvl(t2.AFFIRM_AMT,0) AFFIRM_AMT,
		/*超额业绩报酬-确认份额*/
		nvl(t2.AFFIRM_NUM,0) AFFIRM_NUM

FROM
	dis_prod_plan t
	/*
		查询根据自动赎回日查询超额业绩报酬
	*/
	left join REP_FLOAT_FEE t2 on t2.status = 'E' and t.auto_redeem_date = t2.AFFIRM_DATE and t2.PROD_ID = #{prodId}
where
   t.operation_start_date <= #{endDate}
   AND t.PROD_ID = #{pprodId}
order by operation_start_date desc
